axis x line = middle,
axis equal, 
grid = both, grid style={opacity=0.5},
xmin = -3.5, xmax = 3.5,
ymin = -2.5, ymax = 5.5,
xtick = {-4,4}, ytick = {-4,4},
minor xtick={-7,-6,...,7}, minor ytick={-7,-6,...,7},
%xticklabels={,,}, %yticklabels={,,},
xlabel = {$x$}, ylabel = {$y$},
xlabel style={below right}, ylabel style={above right},
every axis x label/.style={at={(ticklabel* cs:1.02)}, anchor=west,},
every axis y label/.style={at={(ticklabel* cs:1.02)}, anchor=south,}
]

% First set
\def\A 
{
		plot[domain=-10:10, samples=100] 
		(axis cs: {\x}, {(\x)^2}) -- cycle
	% Ancors:
	% (current page.north east) 
	% (current page.south east) 
	% (current page.south west) 
	% (current page.north west) 
}

% Second set
\def\B 
{
		plot[domain=-10:10, samples=100] 
		(axis cs: {\x}, {2-\x}) -- (current page.south east) -- (current page.north west) -- cycle
	% Ancors:
	% (current page.north east) 
	% (current page.south east) 
	% (current page.south west) 
	% (current page.north west) 
}


% Fill
\begin{scope} % (U \ B) cap (U \ A)
	\clip[invclip] \B;
	\begin{scope} % U \ A

		\fill[fill style]\A;
	\end{scope}
\end{scope}

% Edges
\begin{scope} % A
	\clip[invclip] \B;
	\draw[exclude style] \A;
\end{scope}

\begin{scope} % B
	\clip \A;
	\draw[exclude style] \B;
\end{scope}

